#!/usr/bin/env bash
set -euo pipefail
: "${GRANDIOSE_STAGE0_BOOTSTRAP_EXPECTED:=23113469}"
readonly root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; readonly compiler="$root/target/debug/grc-stage0"; readonly support="$root/self-host-stage0/runtime/compiler_support.glorious"; readonly probe="${GRANDIOSE_STAGE0_BOOTSTRAP_PROBE:-$root/self-host-stage0/probes/bootstrap.glorious}"; readonly expected="${GRANDIOSE_STAGE0_BOOTSTRAP_EXPECTED:-23113468}"; readonly manifest="$root/self-host-stage0/src/bootstrap/bootstrap.glorious"; readonly identity="$root/self-host-stage0/src/identity/identity.glorious"; readonly source="$root/self-host-stage0/src/source/source.glorious"; readonly scanner="$root/self-host-stage0/src/scanner/scanner.glorious"; readonly request="$root/self-host-stage0/src/request/request.glorious"; readonly types="$root/self-host-stage0/src/types/types.glorious"; readonly signature="$root/self-host-stage0/src/signature/signature.glorious"; readonly pattern="$root/self-host-stage0/src/pattern/pattern.glorious"; readonly body="$root/self-host-stage0/src/body/body.glorious"; readonly core="$root/self-host-stage0/src/core/core.glorious"; readonly storage="$root/self-host-stage0/src/mir_storage/mir_storage.glorious"; readonly mir="$root/self-host-stage0/src/mir/mir.glorious"; readonly runtime_manifest="$root/self-host-stage0/src/runtime_manifest/runtime_manifest.glorious"; readonly backend="$root/self-host-stage0/src/vm_backend/vm_backend.glorious"; readonly library="$root/self-host-stage0/probes/bootstrap_library.glorious"
if [[ "${GRANDIOSE_STAGE0_ALREADY_BUILT:-0}" != 1 ]]; then cargo build -q -p grandiose-stage0 --bin grc-stage0; fi
output="$("$compiler" --root-package bootstrap-probe@0.1.0 --source compiler_support@0.1.0 src/lib.glorious "$support" --source bootstrap-library@0.1.0 src/lib.glorious "$library" --source bootstrap-library@0.1.0 src/runtime_manifest/runtime_manifest.glorious "$runtime_manifest" --source bootstrap-library@0.1.0 src/bootstrap/bootstrap.glorious "$manifest" --source bootstrap-library@0.1.0 src/identity/identity.glorious "$identity" --source bootstrap-library@0.1.0 src/source/source.glorious "$source" --source bootstrap-library@0.1.0 src/scanner/scanner.glorious "$scanner" --source bootstrap-library@0.1.0 src/request/request.glorious "$request" --source bootstrap-library@0.1.0 src/types/types.glorious "$types" --source bootstrap-library@0.1.0 src/signature/signature.glorious "$signature" --source bootstrap-library@0.1.0 src/pattern/pattern.glorious "$pattern" --source bootstrap-library@0.1.0 src/body/body.glorious "$body" --source bootstrap-library@0.1.0 src/core/core.glorious "$core" --source bootstrap-library@0.1.0 src/mir_storage/mir_storage.glorious "$storage" --source bootstrap-library@0.1.0 src/mir/mir.glorious "$mir" --source bootstrap-library@0.1.0 src/vm_backend/vm_backend.glorious "$backend" --runtime-standard-library compiler_support@0.1.0 --runtime-leaf branch-bool crate branch_bool --runtime-leaf blake3 crate __g1_blake3 --runtime-leaf text-as-bytes crate __g1_text_as_bytes --runtime-leaf text-eq crate __g1_text_eq --runtime-leaf bytes-len crate __g1_bytes_len --runtime-leaf bytes-get crate __g1_bytes_get --runtime-leaf bytes-slice crate __g1_bytes_slice --runtime-leaf bytes-concat crate __g1_bytes_concat --runtime-leaf bytes-from-array-move crate __g1_bytes_from_array_move --runtime-leaf int-shr crate __g1_int_shr --runtime-leaf int-convert-wrapping-to-u32 crate __g1_int_convert_wrapping_to_u32 --runtime-leaf int-convert-wrapping-to-u64 crate __g1_int_convert_wrapping_to_u64 --runtime-leaf int-convert-wrapping-to-u8 crate __g1_int_convert_wrapping_to_u8 --runtime-leaf int-convert-checked-to-i64 crate __g1_int_convert_checked_to_i64 --runtime-leaf int-wrapping-add crate __g1_int_wrapping_add --runtime-leaf int-wrapping-sub crate __g1_int_wrapping_sub --runtime-leaf int-wrapping-mul crate __g1_int_wrapping_mul --runtime-leaf int-checked-div crate __g1_int_checked_div --runtime-leaf array-empty crate __g1_array_empty --runtime-leaf array-len crate __g1_array_len --runtime-leaf array-get-move crate __g1_array_get_move --runtime-leaf array-pop-move crate __g1_array_pop_move "$@" run "$probe")"
[[ "$output" == "$expected" ]] || { echo "self-host bootstrap check: expected bounded source bootstrap codec behavior, got $output" >&2; exit 1; }; printf '%s\n' "$output"
